/* xx_zfsf_extractor.c - search raw data for ZFSF.
 *
 * Scans for:
 *   5A 46 53 46 at +0  ("ZFSF")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the zfsf reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/zfsf/xx_zfsf.h"

static const uint8_t k_anchor0[] = { 0x5A, 0x46, 0x53, 0x46 };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_ZFSF };

static Abstractformat *xx_zfsf_search_open(xx_io_device *window) {
    xx_zfsf *reader = xx_zfsf_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_zfsf_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_zfsf_free((xx_zfsf *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_zfsf_search_open, xx_zfsf_search_close
};

static xx_format_search_state *xx_zfsf_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_zfsf_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_zfsf_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_zfsf_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_zfsf_extractor = {
    xx_zfsf_create_format_search,
    xx_zfsf_get_current_format_info,
    xx_zfsf_format_search_find_next,
    xx_zfsf_free_format_search
};
